local function C_b()
local script = G2L["b"];
	local button = script.Parent
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	local Workspace = game:GetService("Workspace")

	local flicker = false
	local allParts = {} -- will store all BaseParts

	-- function to collect all parts
	local function getAllParts()
		allParts = {}
		for _, part in pairs(Workspace:GetDescendants()) do
			if part:IsA("BasePart") then
				table.insert(allParts, part)
			end
		end
	end

	-- function to start rainbow flicker
	local function startFlicker()
		flicker = true
		getAllParts()
		task.spawn(function()
			while flicker do
				for _, part in pairs(allParts) do
					part.BrickColor = BrickColor.Random()
				end
				task.wait(0.1) -- adjust speed
			end
		end)
	end

	-- function to stop flicker
	local function stopFlicker()
		flicker = false
	end

	button.MouseButton1Click:Connect(function()
		if flicker then
			stopFlicker()
		else
			startFlicker()
		end
	end)

end;
