	local Terrain = workspace:FindFirstChildOfClass("Terrain")

	button.MouseButton1Click:Connect(function()
		if not Terrain then return end

		-- Determine bounds of the map by checking all anchored parts
		local minX, minZ = math.huge, math.huge
		local maxX, maxZ = -math.huge, -math.huge

		for _, part in pairs(workspace:GetDescendants()) do
			if part:IsA("BasePart") and part.Anchored then
				local pos = part.Position
				local halfSize = part.Size / 2
				minX = math.min(minX, pos.X - halfSize.X)
				maxX = math.max(maxX, pos.X + halfSize.X)
				minZ = math.min(minZ, pos.Z - halfSize.Z)
				maxZ = math.max(maxZ, pos.Z + halfSize.Z)
			end
		end

		-- Fill the entire map with water for your client
		Terrain:FillBlock(
			CFrame.new((minX + maxX)/2, 25, (minZ + maxZ)/2), -- center position
			Vector3.new(maxX - minX, 50, maxZ - minZ),        -- size of the water block
			Enum.Material.Water
		)
	end)

end;
